22	     * date's own year before 1 July, or the next year on or after 1 July.
23	     */
24	    public static int of(LocalDate date) {
25	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
26	    }
27	
28	    /** The fiscal year of {@code date} as 'FY<YY>' (e.g. 'FY26'), the last two digits of {@link #of}. */
29	    public static String label(LocalDate date) {
30	        return String.format("FY%02d", of(date) % 100);
31	    }
