3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * SHA-256 hex digest of a string's UTF-8 bytes. Shared by the deterministic identifiers the
9	 * owner pipeline derives (the household id and the customer code hash), so they all agree on
10	 * one digest representation.
11	 */
12	public final class Sha256 {
13	
14	    private Sha256() {
15	    }
16	
17	    /** The lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. */
18	    public static String hex(String value) {
19	        try {
20	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
21	            StringBuilder sb = new StringBuilder(digest.length * 2);
22	            for (byte b : digest) {
23	                sb.append(String.format("%02x", b));
24	            }
25	            return sb.toString();
26	        }
27	        catch (NoSuchAlgorithmException e) {
28	            throw new IllegalStateException("SHA-256 not available", e);
29	        }
30	    }
31	}
