1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Objects;
4	import java.util.Set;
5	import java.util.stream.Collectors;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.util.CustomerCode;
11	import org.springframework.samples.petclinic.util.OwnerRegion;
12	
13	/**
14	 * Assigns a newly built owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where
15	 * REGION is the owner's {@link OwnerRegion region} (derived from its postcode) and HASH8 is the
16	 * first 8 upper-case hex characters of {@code SHA-256(normalizedTelephone + lastName)} (e.g.
17	 * 'NSW-1A2B3C4D'). The code is a deterministic function of the owner's region and identity, so on
18	 * the rare collision with an existing owner's code it is de-duplicated by appending {@code '-<n>'}
19	 * with the smallest {@code n >= 2} that stays unique. The telephone has already been normalized to
20	 * E.164 earlier in the pipeline, so {@link Owner#getTelephone()} is the normalized telephone the
21	 * hash covers. Runs before the owner is persisted, so {@link OwnerRepository#findAll()} returns
22	 * only the codes taken by existing owners and never the owner itself. The code is stored in place
23	 * on the built entity so it is persisted and returned; the membership number, its check digit and
24	 * the locality are all derived from it. Runs after {@link BuildOwner}.
25	 */
26	public class AssignOwnerCustomerCode {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String region = OwnerRegion.of(owner.getPostcode(), owner.getCity());
30	        String code = CustomerCode.of(region, owner.getTelephone(), owner.getLastName());
31	        Set<String> taken = ownerRepository.findAll().stream()
32	                .map(Owner::getCustomerCode)
33	                .filter(Objects::nonNull)
34	                .collect(Collectors.toSet());
35	        owner.setCustomerCode(CustomerCode.deduplicate(code, taken));
36	    }
37	}
