1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.util.Sha256;
4	import org.springframework.samples.petclinic.util.Soundex;
5	
6	/**
7	 * The derived duplicate-detection identity of an owner: a single SHA-256 key that consolidates the
8	 * telephone, email and phonetic last name the create pipeline rejects duplicates by. The key is the
9	 * SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
10	 *
11	 * <p>Two owners are duplicates only when their <em>whole</em> keys are equal. Because the telephone
12	 * is part of the key, two owners with the same last name and postcode but different telephones have
13	 * different keys and are both allowed — only an exact full-key match is a duplicate.
14	 */
15	public final class OwnerIdentity {
16	
17	    private OwnerIdentity() {
18	    }
19	
20	    /**
21	     * The identity key for the given canonical components. The telephone is folded to its
22	     * {@link OwnerTelephone#toE164(String) E.164} form, the email to its
23	     * {@link OwnerEmail#normalize(String) lower-cased} form and the last name to its
24	     * {@link Soundex#encode(String) Soundex} code; an absent email or last name contributes the
25	     * empty string. The three are joined by {@code '|'} and SHA-256 hex digested.
26	     */
27	    public static String key(String telephone, String email, String lastName) {
28	        String raw = normalizedTelephone(telephone) + "|" + normalizedEmail(email) + "|" + Soundex.encode(lastName);
29	        return Sha256.hex(raw);
30	    }
31	
32	    private static String normalizedTelephone(String telephone) {
33	        return OwnerTelephone.toE164(telephone).orElse(orEmpty(telephone));
34	    }
35	
36	    private static String normalizedEmail(String email) {
37	        return (email == null || email.isBlank()) ? "" : OwnerEmail.normalize(email);
38	    }
39	
40	    private static String orEmpty(String value) {
41	        return value == null ? "" : value;
42	    }
43	}
