1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.util.Sha256;
6	
7	/**
8	 * Identity of an owner's household. Two owners live in the same household when they share the
9	 * same last name and postcode. The last name is compared case-insensitively with collapsed
10	 * whitespace and the postcode as supplied.
11	 *
12	 * <p>The {@link #id(String, String) household id} is derived deterministically from that
13	 * canonical key, so every owner with the same last name and postcode computes the same stable
14	 * identifier automatically — no owner has to opt in for the link to form.
15	 */
16	final class Household {
17	
18	    /** Number of leading hex characters of the digest that make up the household id. */
19	    private static final int ID_LENGTH = 12;
20	
21	    private Household() {
22	    }
23	
24	    /**
25	     * Canonical household key: the last name trimmed, internal whitespace collapsed and
26	     * lower-cased, joined to the postcode with {@code '|'} so distinct pairs never collide.
27	     */
28	    static String key(String lastName, String postcode) {
29	        return canonical(lastName) + "|" + orEmpty(postcode);
30	    }
31	
32	    /**
33	     * Stable identifier shared by every owner in the household: the first {@value #ID_LENGTH} hex
34	     * characters of the SHA-256 digest of the canonical {@link #key(String, String) key}, so any
35	     * two owners with the same last name and postcode derive the same value.
36	     */
37	    static String id(String lastName, String postcode) {
38	        return Sha256.hex(key(lastName, postcode)).substring(0, ID_LENGTH);
39	    }
40	
41	    /** Case-insensitive form with leading/trailing and repeated internal whitespace collapsed. */
42	    private static String canonical(String value) {
43	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
44	    }
45	
46	    private static String orEmpty(String value) {
47	        return value == null ? "" : value;
48	    }
49	}
