11	
12	/**
13	 * Single sink for owner audit output. All entries go to the dedicated {@code AUDIT} logger so the
14	 * audit trail has one owner. On each create it emits both the human-readable audit line and an
15	 * immutable {@link OwnerCreatedEvent} rendered as JSON, stamping the event with the next value of a
16	 * process-wide monotonic sequence.
17	 */
18	@Component
19	public class OwnerAuditTrail {
20	
21	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
22	
23	    private static final JsonMapper JSON = JsonMapper.builder().build();
24	
25	    private final AtomicLong sequence = new AtomicLong();
26	
27	    /**
28	     * Records a successful owner create: the human-readable line and the structured
29	     * {@code OWNER_CREATED} event. The {@code membershipNumber} is derived by the caller so this
30	     * sink stays independent of the web mapping layer.
31	     */
32	    public void ownerCreated(Owner owner, String membershipNumber) {
33	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
34	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
35	                owner.getMembershipLevel(), membershipNumber);
36	        OwnerCreatedEvent event = OwnerCreatedEvent.of(this.sequence.incrementAndGet(), owner);
37	        AUDIT.info("{}", event.toJson(JSON));
38	    }
39	}
