1	package org.springframework.samples.petclinic.rest.audit;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	import tools.jackson.databind.json.JsonMapper;
6	
7	/**
8	 * Immutable structured audit event recording that an owner was created, emitted alongside the
9	 * human-readable audit line for {@code POST /api/owners}. Serialized to a JSON object
10	 * {@code {seq, ownerId, customerCode, membershipLevel, event}} where {@code event} is always
11	 * {@code OWNER_CREATED} and {@code seq} is a monotonically increasing sequence across creates.
12	 *
13	 * <p>The event carries the owner's <em>current primary identifier</em>. Today that is the
14	 * {@code customerCode}; when the customerCode is later unified into the {@code memberId} the event
15	 * must carry the memberId instead. That identifier is resolved in one place
16	 * ({@link #primaryIdentifier(Owner)}) so the switch is a single-line change.
17	 */
18	public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, Integer membershipLevel,
19	        String event) {
20	
21	    private static final String EVENT_TYPE = "OWNER_CREATED";
22	
23	    /** Builds the event for a persisted {@code owner} at the given monotonic {@code seq}. */
24	    public static OwnerCreatedEvent of(long seq, Owner owner) {
25	        return new OwnerCreatedEvent(seq, owner.getId(), primaryIdentifier(owner),
26	                owner.getMembershipLevel(), EVENT_TYPE);
27	    }
28	
29	    /**
30	     * The owner's current primary identifier. Today the {@code customerCode}; when the customerCode
31	     * is unified into the {@code memberId} this is the single line that changes.
32	     */
33	    private static String primaryIdentifier(Owner owner) {
34	        return owner.getCustomerCode();
35	    }
36	
37	    /** Renders this event as a JSON object string. */
38	    public String toJson(JsonMapper mapper) {
39	        return mapper.writeValueAsString(this);
40	    }
