27	@Mapper(uses = PetMapper.class)
28	public interface OwnerMapper {
29	
30	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
31	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
32	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
33	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
34	    @Mapping(target = "initials", expression = "java(initials(owner))")
35	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
36	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
37	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
38	    @Mapping(target = "locality", expression = "java(locality(owner))")
39	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
40	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
41	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
42	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
43	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    /** The owner's canonical relative URL, '/api/owners/' followed by its id. */
47	    default String selfLink(Owner owner) {
48	        return "/api/owners/" + owner.getId();
49	    }
50	
51	    /** The owner's stored E.164 telephone formatted for people to read (country code, space,
52	     *  national digits grouped in threes), or null when it is not a recognised E.164 number.
53	     *  See {@link OwnerTelephone#toDisplay}. */
54	    default String telephoneDisplay(Owner owner) {
55	        return OwnerTelephone.toDisplay(owner.getTelephone()).orElse(null);
56	    }
57	
58	    /** The owner's name formatted as 'LastName, FirstName' from the stored names. */
59	    default String displayName(Owner owner) {
60	        return owner.getLastName() + ", " + owner.getFirstName();
61	    }
62	
63	    /** The owner's salutation: the courtesy title followed by a space and the lastName
64	     *  (e.g. 'DR Franklin'), or just the lastName when no title was supplied. */
65	    default String salutation(Owner owner) {
66	        String title = owner.getTitle();
67	        return title == null || title.isBlank()
68	                ? owner.getLastName()
69	                : title + " " + owner.getLastName();
70	    }
71	
72	    /** The upper-cased first letters of firstName and lastName, dot-separated with a
73	     *  trailing dot, e.g. 'J.S.'. */
74	    default String initials(Owner owner) {
75	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
76	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
77	    }
78	
79	    /** The membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two digits of
80	     *  the registrationDate's fiscal year (see {@link FiscalYear}, e.g. 'NSW-1A2B3C4D-M27'). Null
81	     *  when either source field is absent. */
82	    default String membershipNumber(Owner owner) {
83	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
84	            return null;
85	        }
86	        return String.format("%s-M%02d", owner.getCustomerCode(), FiscalYear.of(owner.getRegistrationDate()) % 100);
87	    }
88	
89	    /** The registrationDate's fiscal year as 'FY&lt;YY&gt;' (see {@link FiscalYear}, e.g. 'FY27').
90	     *  Null when the registrationDate is absent. */
91	    default String fiscalYear(Owner owner) {
92	        return owner.getRegistrationDate() == null ? null : FiscalYear.label(owner.getRegistrationDate());
93	    }
94	
95	    /** The Luhn check digit over the digits of the customerCode. Null when the customerCode
96	     *  is absent. */
97	    default Integer checkDigit(Owner owner) {
98	        return owner.getCustomerCode() == null ? null : Luhn.checkDigit(owner.getCustomerCode());
99	    }
100	
101	    /** The owner's locality: the REGION segment of its customerCode, which is the canonical region
102	     *  the code was built from. Falls back to deriving the region straight from the postcode and
103	     *  city when the customerCode is absent (so an owner without one still resolves a locality). */
104	    default String locality(Owner owner) {
105	        return owner.getCustomerCode() != null
106	                ? CustomerCode.region(owner.getCustomerCode())
107	                : OwnerRegion.of(owner.getPostcode(), owner.getCity());
108	    }
109	
110	    /** The owner's timezone: the IANA name from the fixed region-to-timezone table
111	     *  (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane), keyed
112	     *  off the owner's {@link #locality locality}. Null when the region has no mapped timezone. */
113	    default String timezone(Owner owner) {
114	        return RegionTimezone.of(locality(owner));
115	    }
116	
117	    /** The owner's preferred contact method: 'EMAIL' when an email address is present,
118	     *  otherwise 'PHONE'. */
119	    default String contactPreference(Owner owner) {
120	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
121	    }
122	
123	    /** The owner's derived duplicate-detection identity key: the SHA-256 hex of the normalized
124	     *  telephone, lower-cased email and soundex(lastName) joined by '|'. See {@link OwnerIdentity#key}. */
125	    default String identityKey(Owner owner) {
126	        return OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
127	    }
128	
129	    /** The owner's age band derived from its birthDate against its registrationDate, or null when
130	     *  either date is absent. See {@link AgeBand}. */
131	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
132	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
133	            return null;
134	        }
135	        return OwnerDto.AgeBandEnum.fromValue(AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()));
136	    }
137	
138	    /** The owner's marketing segment '&lt;TIER&gt;_&lt;AREA&gt;', derived from its membershipLevel and
139	     *  {@link #locality locality}. See {@link OwnerSegment}. */
140	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
141	        return OwnerDto.OwnerSegmentEnum.fromValue(OwnerSegment.of(owner.getMembershipLevel(), locality(owner)));
142	    }
143	
144	    Owner toOwner(OwnerDto ownerDto);
145	
146	    @Mapping(target = "id", ignore = true)
147	    @Mapping(target = "pets", ignore = true)
148	    Owner toOwner(OwnerFieldsDto ownerDto);
149	
150	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
151	
152	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
153	
154	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
155	        OwnerPageDto ownerPageDto = new OwnerPageDto();
156	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
157	        ownerPageDto.setPage(ownerPage.getNumber());
158	        ownerPageDto.setSize(ownerPage.getSize());
159	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
160	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
161	        return ownerPageDto;
162	    }
163	}
