18	    public static String of(Integer membershipLevel, String region) {
19	        String tier = membershipLevel != null && membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
20	        String area = CityRegion.isKnown(region) ? "METRO" : "REGIONAL";
21	        return tier + "_" + area;
22	    }
